def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_last = op[-1]
    if n < 10:
        if opp_last == 'D':
            if n >= 2 and my[-1] == 'D' and my[-2] == 'D' and op[-2] == 'D':
                return 'C'
            return 'D'
        else:
            return 'C'
    lookback = min(n, 10)
    recent_op = op[-lookback:]
    recent_coop = recent_op.count('C')
    if recent_coop <= 2:
        return 'D'
    if opp_last == 'D':
        if my[-1] == 'D' and my[-2] == 'D' and op[-2] == 'D':
            return 'C'
        return 'D'
    else:
        return 'C'
